"""Hatching Hearths art (your painted hearth room, with its own title).
img(name) gives the surface; scaled(name, w, h) a cached resized copy."""
import base64
import io
import pygame

# everything in hearth_bg.jpg pixels (the picture is 1672 x 941, its own title is kept)
ART_W, ART_H = 1672, 941
HEARTHS = [(285 + 285 * i, 255, 250, 405) for i in range(4)]   # each hearth: x, y, w, h (plate at the top, arch below)
PLATE_H = 72                       # the brass plate across the top of each hearth
CRADLE = [(409 + 284 * i, 600) for i in range(4)]              # where an egg sits in each painted cradle (centre x, rim y)
LIGHTS = ((372, 115, 50), (1302, 115, 50), (200, 560, 40))     # the two torches and the lantern
PNG = {
  'hearth_bg': ('jpg', ''),
}
_C = {}


def has(name):
  return name in PNG


def img(name):
  s = _C.get(name)
  if s is None:
    ext, data = PNG[name]
    s = pygame.image.load(io.BytesIO(base64.b64decode(data)), 'art.' + ext)
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[name] = s
  return s


def scaled(name, w, h, smooth=True):
  k = (name, int(w), int(h))
  s = _C.get(k)
  if s is None:
    src = img(name)
    fn = getattr(pygame.transform, 'smoothscale', None) if smooth else None
    try:
      s = (fn or pygame.transform.scale)(src, (max(1, int(w)), max(1, int(h))))
    except Exception:
      s = pygame.transform.scale(src, (max(1, int(w)), max(1, int(h))))
    _C[k] = s
  return s
